import numpy as np
import matplotlib.pyplot as plt

# Define distances from 0 to 4 meters
distances = np.linspace(0, 4.0, 600)

# Different std values to compare
std_values = [0.05, 0.1, 0.3, 1.0, 2.0]

# Custom colors (you can change these)
colors = ["red", "orange", "green", "blue", "purple"]

sum_vals = np.zeros(len(distances))

plt.figure(figsize=(10, 6))

for std, color in zip(std_values, colors):
    rewards = 1 - np.tanh(distances / std)
    sum_vals = sum_vals + rewards
    plt.plot(distances, rewards, color=color, linewidth=2.5, label=f"σ = {std}")

plt.rcParams.update({'font.size': 15})

plt.title("Response Curve for Different Standard Deviations")
plt.xlabel("Distance x [m]", fontsize=20)
plt.ylabel("f(x) = 1 − tanh(x / σ)", fontsize=20)
plt.grid(True, linestyle="--", alpha=0.6)
plt.legend()
plt.tight_layout()
plt.show()



