# ---- Plot: Position error over time ----
plt.figure(figsize=(10, 6))

for label, y in zip(data_labeled, Data):
    y = np.asarray(y, dtype=float)
    if y.size == 0:
        continue

    time = np.arange(y.size) * dt_policy
    plt.plot(time, y, linewidth=2.5, label=label)

plt.title("Position Tracking Error")
plt.xlabel("Time [s]")
plt.ylabel("Position Error [m]")
plt.grid(True)
plt.legend()
plt.tight_layout()
plt.show()

# ---- Sanity check: are PPO and TRPO identical? ----
print("PPO and TRPO arrays identical (allclose)?",
      np.allclose(np.asarray(PPO_position_tracking_RMSE, float),
                  np.asarray(TRPO_position_tracking_RMSE, float)))

# ---- Metrics table (assumes y is per-step error magnitude, >= 0) ----
print("\nAlgorithm | MAE (m) | RMSE (m) | STD (m) | Max Error (m)")
print("-----------------------------------------------------------")

for label, y in zip(data_labeled, Data):
    y = np.asarray(y, dtype=float)
    if y.size == 0:
        continue

    mae = np.mean(y)
    rmse = np.sqrt(np.mean(y**2))
    std = np.std(y)
    max_err = np.max(y)

    # ---- Plot ----
    plt.figure()
    plt.hist(y, bins=100)
    plt.title(f"{label} Error Distribution")
    plt.xlabel("Tracking Error (m)")
    plt.ylabel("Frequency")
    plt.grid(True)
    plt.show()

    print(f"{label:7s} | {mae:8.4f} | {rmse:9.4f} | {std:7.4f} | {max_err:12.4f}")